"use client";

import { useEffect } from "react";

import { formatMatches, FormatMatchesError } from "@/lib/matches";

const DEFAULT_BACKEND = "http://127.0.0.1:8000";

const MATCHES_BASE =
  (typeof process !== "undefined" &&
    process.env.NEXT_PUBLIC_BACKEND_URL?.replace(/\/$/, "")) ||
  DEFAULT_BACKEND;

type MatchesApiPayload = {
  raw_fixtures?: unknown;
};

type GlobalFetchGuard = typeof globalThis & {
  __prediktiaDevFormatMatchesFetch?: boolean;
};

/**
 * Evita un segundo fetch cuando el árbol se desmonta/remonta (p. ej. Strict Mode
 * o remontajes de desarrollo). Se resetea al recargar la página (nuevo JS global).
 */
function shouldSkipDuplicateFetch(): boolean {
  if (typeof globalThis === "undefined") {
    return false;
  }
  const g = globalThis as GlobalFetchGuard;
  if (g.__prediktiaDevFormatMatchesFetch) {
    return true;
  }
  g.__prediktiaDevFormatMatchesFetch = true;
  return false;
}

export function FormatMatchesConsole() {
  useEffect(() => {
    if (shouldSkipDuplicateFetch()) {
      return;
    }

    console.log("FETCH START");

    const base = MATCHES_BASE;
    let cancelled = false;

    async function run() {
      try {
        const res = await fetch(`${base}/matches`, { cache: "no-store" });
        if (!res.ok) {
          throw new Error(`HTTP ${res.status} al llamar ${base}/matches`);
        }

        const data = (await res.json()) as MatchesApiPayload;
        const clean = formatMatches(data.raw_fixtures, {
          onSkip: ({ index, reason }) => {
            console.warn(`[formatMatches] Fila omitida #${index}: ${reason}`);
          },
        });

        if (cancelled) {
          return;
        }

        console.log("[Prediktia] Partidos formateados:", clean);
      } catch (err) {
        if (cancelled) {
          return;
        }

        if (err instanceof FormatMatchesError) {
          console.error("[formatMatches]", err.code, err.message, err.cause);
          return;
        }

        console.error("[dev/format-matches]", err);
      }
    }

    void run();

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="mx-auto max-w-xl rounded-xl border border-gray-800 bg-gray-900 p-6 text-gray-200">
      <h1 className="text-lg font-semibold text-white">Dev · formatMatches</h1>
      <p className="mt-2 text-sm text-gray-400">
        Abre las herramientas de desarrollo del navegador (F12 → Consola). Se
        imprime el array limpio al cargar la página. Backend esperado en{" "}
        <code className="rounded bg-gray-800 px-1 py-0.5 text-xs">
          {process.env.NEXT_PUBLIC_BACKEND_URL ?? DEFAULT_BACKEND}
        </code>
        .
      </p>
      <p className="mt-3 text-xs text-gray-500">
        Opcional: define{" "}
        <code className="rounded bg-gray-800 px-1">NEXT_PUBLIC_BACKEND_URL</code>{" "}
        en <code className="rounded bg-gray-800 px-1">frontend/.env.local</code>.
      </p>
    </div>
  );
}
